#include "systick.h"

void *dualtimer_handler = NULL;

// /*Global control macro*/
#define dualtimer_test_channel   (CSK_TIMER_CHANNEL_1)
#define dualtimer_reload_count   (1500)

static volatile uint32_t dualtimer_flag = 0;

/*Callback*/
static void dualtimer_eventcallback(uint32_t event, void *workspace)
{
    dualtimer_flag = 1;
}

static void dualtimer_test_init(void)
{
    DUALTIMERS_Initialize(dualtimer_handler);
    DUALTIMERS_PowerControl(dualtimer_handler, CSK_POWER_FULL);
    DUALTIMERS_SetTimerCallback(dualtimer_handler, dualtimer_test_channel, dualtimer_eventcallback, NULL);
    DUALTIMERS_SetTimerPeriodByCount(dualtimer_handler, dualtimer_test_channel, dualtimer_reload_count);
}

static void dualtimer_test_uninit(void)
{
    DUALTIMERS_StopTimer(dualtimer_handler, dualtimer_test_channel);
    DUALTIMERS_PowerControl(dualtimer_handler, CSK_POWER_OFF);
    DUALTIMERS_Uninitialize(dualtimer_handler);
}

void setUp(void)
{
    /* This is run before EACH TEST */
    dualtimer_handler = DUALTIMERS1();
    dualtimer_test_init();
    enable_GINT();
}

void tearDown(void)
{
    dualtimer_test_uninit();
    disable_GINT();
}

void test_dualtimer_pointer_verify(void)
{
    TEST_ASSERT_NOT_NULL(dualtimer_handler);
}

void test_dualtimer_interrupt_one_shot(void)
{
    DUALTIMERS_Control(dualtimer_handler, CSK_TIMER_PRESCALE_Divide_1 | \
                       CSK_TIMER_SIZE_16Bit | \
                       CSK_TIMER_MODE_OneShot | \
                       CSK_TIMER_INTERRUPT_Enabled, dualtimer_test_channel);


    DUALTIMERS_StartTimer(dualtimer_handler, dualtimer_test_channel);

    while (dualtimer_flag == 0);
    dualtimer_flag = 0;

    uint32_t count = 0;
    DUALTIMERS_ReadTimerCount(dualtimer_handler, dualtimer_test_channel, &count);

    TEST_ASSERT_EQUAL_UINT32(0, count);
}

void test_dualtimer_interrupt_free_running(void)
{
    DUALTIMERS_Control(dualtimer_handler, CSK_TIMER_PRESCALE_Divide_1 | \
                       CSK_TIMER_SIZE_16Bit | \
                       CSK_TIMER_MODE_FreeRunning | \
                       CSK_TIMER_INTERRUPT_Enabled, dualtimer_test_channel);

    DUALTIMERS_StartTimer(dualtimer_handler, dualtimer_test_channel);

    while (dualtimer_flag == 0);
    dualtimer_flag = 0;

    uint32_t count = 0;
    DUALTIMERS_ReadTimerCount(dualtimer_handler, dualtimer_test_channel, &count);

    TEST_ASSERT_NOT_EQUAL_UINT32(0, count);
}

